mkdir -p /tmp/recon && cat > /tmp/recon/fetch.py <<'EOF'
import json, time, urllib.request, urllib.error, sys
BASE = "http://localhost:8080"
log = open("/tmp/recon/log.txt", "w")
tok = None
def get_token():
    global tok
    while True:
        try:
            req = urllib.request.Request(BASE + "/token", method="POST", data=b"")
            with urllib.request.urlopen(req, timeout=30) as r:
                tok = json.load(r)["token"]; log.write(f"token {tok}\n"); return
        except urllib.error.HTTPError as e:
            handle_err(e, "/token")
def handle_err(e, path):
    body = e.read()[:300]
    ra = e.headers.get("Retry-After")
    log.write(f"{path} -> {e.code} retry-after={ra} hdrs={dict(e.headers)} body={body!r}\n"); log.flush()
    if e.code == 429:
        time.sleep(float(ra) if ra else 2)
    elif e.code >= 500:
        time.sleep(float(ra) if ra else 1)
def call(path):
    global tok
    if tok is None: get_token()
    while True:
        req = urllib.request.Request(BASE + path, headers={"Authorization": f"Bearer {tok}"})
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                return r.status, json.load(r)
        except urllib.error.HTTPError as e:
            if e.code == 401:
                log.write(f"{path} -> 401 {e.read()[:200]!r}\n"); get_token(); continue
            if e.code == 404:
                return 404, json.loads(e.read() or b"null")
            handle_err(e, path)
        except (urllib.error.URLError, ConnectionError, json.JSONDecodeError, TimeoutError) as e:
            log.write(f"{path} -> exc {e!r}\n"); time.sleep(1)
pages = []
path = "/orders?page=1"
while path:
    st, d = call(path)
    pages.append(d)
    log.write(f"got {path}: page={d.get('page')} total={d.get('total_pages')} n={len(d['items'])} next={d.get('next')}\n"); log.flush()
    path = d.get("next")
json.dump(pages, open("/tmp/recon/pages.json", "w"))
cids = sorted({o["customer_id"] for p in pages for o in p["items"]})
custs = {}
for c in cids:
    st, d = call(f"/customers/{c}")
    custs[c] = {"status": st, "body": d}
json.dump(custs, open("/tmp/recon/customers.json", "w"))
print("pages", len(pages), "customers", len(custs))
EOF
cd /tmp/recon && timeout 590 python3 -I fetch.py; tail -5 log.txt; grep -c -E '429|401|-> 5|exc' log.txt

